function noise(s:TerrorscapeState,at:TerrorRoom,immediate=false){const a=immediate?s.noises:s.pendingNoises;if(!a.includes(at))a.push(at);if(immediate)log(s,`${TERROR_ROOM_INFO[at].name}에서 소음이 들립니다.`,'NOISE');}
