function startSurvivors(s:TerrorscapeState,now:ServerTime){s.phase='SURVIVORS';s.discoveryDone=false;s.afterLoot='SURVIVORS';s.encounteredLastTurn=s.encounteredThisTurn;s.round++;s.noises=[];s.pendingNoises=[];s.firecracker=false;s.pendingFirecracker=false;s.repaired=false;s.encounter=null;s.sensed=[];s.bonus=0;s.attackBonus=0;s.reappearing=false;s.pings=[];for(const p of s.survivors){p.acted=p.outcome!=='ACTIVE';p.ready=p.outcome!=='ACTIVE';}if(s.separateWays){for(const p of living(s))if(s.keyOwners.filter(k=>k.character===p.character).length>=3&&(p.location==='R1'||p.location==='G5'&&p.hand.some(c=>c.key==='SECRET_MAP'))){p.outcome='ESCAPED';p.acted=true;p.ready=true;log(s,`${TERROR_CHARACTER_INFO[p.character].name} 개별 탈출!`,'WIN');}if(!living(s).length){finish(s,'SEPARATE_WAYS',now);return;}if(!living(s).some(p=>p.character===s.firstDiscover))s.firstDiscover=living(s)[0]!.character;}if(s.rescue!==null){s.rescue--;if(s.rescue<=0){finish(s,'RESCUED',now);return;}}if(!s.separateWays&&s.keys.length>=5&&(living(s).every(p=>p.location==='R1')||living(s).every(p=>p.location==='G5')&&s.survivors.some(p=>p.hand.some(c=>c.key==='SECRET_MAP')))){finish(s,'ESCAPED',now);return;}if(planActive(s,'ROCKET')&&!s.stealth&&!s.encounteredLastTurn&&living(s).every(p=>p.location===living(s)[0]!.location)&&terrorAdjacent(living(s)[0]!.location,s.killerLocation)){finish(s,'STRIKE_BACK',now);return;}if(planActive(s,'PORTAL')&&living(s).every(p=>p.location==='G2')&&['SECRET_MAP','FLASHLIGHT','AMULET'].every(k=>living(s).some(p=>p.hand.some(c=>c.key===k)))){finish(s,'ESCAPED',now);return;}log(s,`${s.round}라운드 · 생존자의 차례입니다.`,'TURN');}
