function move(s:TerrorscapeState,start:TerrorRoom,path:readonly TerrorRoom[],max:number,killer:boolean):{at:TerrorRoom;removed:boolean}{requireRule(path.length>0&&path.length<=max);let at=start,removed=false;for(const to of path){requireRule(terrorAdjacent(at,to));const edge=terrorEdge(at,to);if(s.blocks.includes(edge)){requireRule(killer);s.blocks=s.blocks.filter(e=>e!==edge);removed=true;}at=to;}return {at,removed};}
