function pay(s:TerrorscapeState,ids:readonly TileId[],count:number){requireRule(ids.length===count&&new Set(ids).size===ids.length&&ids.every(id=>s.hand.some(c=>c.cardId===id)));s.killerDiscard.push(...s.hand.filter(c=>ids.includes(c.cardId)));s.hand=s.hand.filter(c=>!ids.includes(c.cardId));}
